function getLang() {
  return localStorage.getItem('fitpower_lang') === 'en' ? 'en' : 'es';
}

function setLang(lang) {
  localStorage.setItem('fitpower_lang', lang === 'en' ? 'en' : 'es');
}

function t(key) {
  const lang = getLang();
  return (I18N[lang] && I18N[lang][key]) || (I18N.es && I18N.es[key]) || key;
}

function applyTranslations(root) {
  const scope = root || document;
  scope.querySelectorAll('[data-i18n]').forEach(function (el) {
    const key = el.getAttribute('data-i18n');
    const mode = el.getAttribute('data-i18n-mode') || 'text';
    const value = t(key);
    if (mode === 'html') {
      el.innerHTML = value;
    } else if (mode === 'placeholder') {
      el.setAttribute('placeholder', value);
    } else if (mode === 'aria') {
      el.setAttribute('aria-label', value);
    } else {
      el.textContent = value;
    }
  });
  document.documentElement.lang = getLang();
}

function toggleLang() {
  setLang(getLang() === 'es' ? 'en' : 'es');
  applyTranslations();
  document.dispatchEvent(new CustomEvent('fitpower:langchange', { detail: { lang: getLang() } }));
}

document.addEventListener('DOMContentLoaded', function () {
  applyTranslations();
  document.querySelectorAll('[data-lang-toggle]').forEach(function (btn) {
    btn.addEventListener('click', function (event) {
      event.preventDefault();
      toggleLang();
    });
  });
});
